import { Hono } from "hono";
import { bearerAuth } from "hono/bearer-auth";
import postgres from "postgres";

const sql = postgres(process.env.DATABASE_URL);
const app = new Hono();

app.use("/api/*", bearerAuth({ token: process.env.API_GATEWAY_SECRET }));

app.get("/api/patients/:patientId/telehealth-record", async (c) => {
  const patientId = c.req.param("patientId");
  const doctorId = c.req.header("X-Doctor-ID");

  if (!doctorId) {
    return c.json({ error: "Missing doctor identifier header" }, 400);
  }

  // Verify clinical care relationship between doctor and patient before returning chart
  const [assignment] = await sql`
    SELECT id FROM clinical_assignments
    WHERE doctor_id = ${doctorId} AND patient_id = ${patientId} AND active = true
  `;

  if (!assignment) {
    return c.json({ error: "Access denied: No active clinical relationship" }, 403);
  }

  const [record] = await sql`
    SELECT id, patient_id, diagnoses, clinical_notes, prescription_history
    FROM telehealth_records
    WHERE patient_id = ${patientId}
  `;

  if (!record) {
    return c.json({ error: "Record not found" }, 404);
  }

  return c.json(record);
});

export default app;
